'use client';

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import type { Transaction } from '@/lib/data';
import { cn } from '@/lib/utils';
import { ArrowUpRight, ArrowDownLeft } from 'lucide-react';
import { Skeleton } from '../ui/skeleton';

type TransactionsCardProps = {
  transactions: Transaction[] | null;
  isLoading: boolean;
};

function TransactionItem({ transaction }: { transaction: Transaction }) {
  const isDebit = transaction.type === 'debit';
  const amountColor = isDebit ? 'text-destructive' : 'text-green-600';
  const amountSign = isDebit ? '-' : '+';

  return (
    <div className="flex items-center gap-4 py-4">
      <Avatar className="h-10 w-10">
        <AvatarImage
          src={transaction.party.avatarUrl}
          alt={transaction.party.name}
        />
        <AvatarFallback>{transaction.party.name.charAt(0)}</AvatarFallback>
      </Avatar>
      <div className="flex-1">
        <p className="font-medium">{transaction.party.name}</p>
        <p className="text-sm text-muted-foreground">
          {transaction.description}
        </p>
      </div>
      <div className="text-right">
        <p className={cn('font-semibold', amountColor)}>
          {amountSign}
          {new Intl.NumberFormat('en-NG', {
            style: 'currency',
            currency: 'NGN', // Assuming NGN, could be dynamic from wallet
          }).format(transaction.amount)}
        </p>
        <p className="text-xs text-muted-foreground">
          {new Date(transaction.date).toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
          })}
        </p>
      </div>
    </div>
  );
}

function TransactionSkeleton() {
  return (
    <div className="flex items-center gap-4 py-4">
      <Skeleton className="h-10 w-10 rounded-full" />
      <div className="flex-1 space-y-2">
        <Skeleton className="h-4 w-2/4" />
        <Skeleton className="h-4 w-3/4" />
      </div>
      <div className="text-right space-y-2">
        <Skeleton className="h-4 w-20" />
        <Skeleton className="h-3 w-12 ml-auto" />
      </div>
    </div>
  )
}

export default function TransactionsCard({
  transactions,
  isLoading,
}: TransactionsCardProps) {
  return (
    <Card>
      <CardHeader>
        <CardTitle>Recent Transactions</CardTitle>
        <CardDescription>
          Here's a list of your recent wallet activity.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <ScrollArea className="h-96">
          <div className="divide-y">
            {isLoading && (
              <>
                <TransactionSkeleton />
                <TransactionSkeleton />
                <TransactionSkeleton />
              </>
            )}
            {!isLoading && transactions && transactions.map((tx) => (
              <TransactionItem key={tx.id} transaction={tx} />
            ))}
          </div>
          {!isLoading && (!transactions || transactions.length === 0) && (
            <div className="flex h-48 items-center justify-center text-muted-foreground">
              No transactions yet.
            </div>
          )}
        </ScrollArea>
      </CardContent>
    </Card>
  );
}
