'use client';

import { useCollection, useDoc, useFirestore, useMemoFirebase, useUser } from '@/firebase';
import { useRouter } from 'next/navigation';
import { useEffect } from 'react';
import { Skeleton } from '@/components/ui/skeleton';
import BackToPreviousButton from '@/components/back-to-previous-button';
import BalanceCard from '@/components/wallet/balance-card';
import ActionsCard from '@/components/wallet/actions-card';
import TransactionsCard from '@/components/wallet/transactions-card';
import { collection, doc, query, orderBy } from 'firebase/firestore';
import type { Wallet, Transaction } from '@/lib/data';

export default function WalletPage() {
  const { user, isUserLoading } = useUser();
  const router = useRouter();
  const firestore = useFirestore();

  useEffect(() => {
    if (!isUserLoading && !user) {
      router.push('/auth');
    }
  }, [user, isUserLoading, router]);

  const walletRef = useMemoFirebase(
    () => (firestore && user ? doc(firestore, 'wallets', user.uid) : null),
    [firestore, user]
  );
  const { data: wallet, isLoading: isWalletLoading } = useDoc<Wallet>(walletRef);

  const transactionsQuery = useMemoFirebase(
    () =>
      firestore && user
        ? query(
            collection(firestore, 'wallets', user.uid, 'transactions'),
            orderBy('date', 'desc')
          )
        : null,
    [firestore, user]
  );

  const { data: transactions, isLoading: areTransactionsLoading } =
    useCollection<Transaction>(transactionsQuery);

  if (isUserLoading || !user) {
    return (
      <div className="container mx-auto px-4 py-12">
        <Skeleton className="mb-8 h-8 w-24" />
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-3">
          <div className="space-y-8 lg:col-span-2">
            <Skeleton className="h-48 w-full" />
            <Skeleton className="h-64 w-full" />
          </div>
          <div className="space-y-8">
            <Skeleton className="h-64 w-full" />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-secondary/50">
      <div className="container mx-auto px-4 py-12">
        <BackToPreviousButton />
        <header className="mb-8 mt-4">
          <h1 className="font-headline text-3xl font-bold md:text-4xl">
            My Digital Wallet
          </h1>
          <p className="mt-2 text-lg text-muted-foreground">
            Welcome back, {user.displayName || user.email}!
          </p>
        </header>

        <div className="grid grid-cols-1 items-start gap-8 lg:grid-cols-3">
          {/* Main column */}
          <div className="space-y-8 lg:col-span-2">
            <BalanceCard
              wallet={wallet}
              isLoading={isWalletLoading}
            />
            <TransactionsCard
              transactions={transactions}
              isLoading={areTransactionsLoading}
            />
          </div>

          {/* Side column */}
          <div className="space-y-8">
            <ActionsCard />
          </div>
        </div>
      </div>
    </div>
  );
}
