'use server';
/**
 * @fileOverview A secure flow for transferring funds between user wallets.
 *
 * - transferFunds - A function that handles the fund transfer process.
 * - TransferFundsInput - The input type for the transferFunds function.
 * - TransferFundsOutput - The return type for the transferFunds function.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import {
  getFirestore,
  runTransaction,
  collection,
  query,
  where,
  getDocs,
  doc,
  writeBatch,
} from 'firebase/firestore';
import { initializeFirebase } from '@/firebase/index';
import { User } from '@/lib/data';

const TransferFundsInputSchema = z.object({
  senderId: z.string().describe('The UID of the user sending the funds.'),
  recipientEmail: z
    .string()
    .email()
    .describe("The email address of the user receiving the funds."),
  amount: z.number().positive().describe('The amount of funds to transfer.'),
});
export type TransferFundsInput = z.infer<typeof TransferFundsInputSchema>;

const TransferFundsOutputSchema = z.object({
  success: z.boolean().describe('Whether the transfer was successful.'),
  message: z.string().describe('A message describing the result.'),
});
export type TransferFundsOutput = z.infer<typeof TransferFundsOutputSchema>;

// This is a server-side flow and should not be exported to the client directly.
// It uses the Firebase Admin SDK principles for secure backend operations.
const transferFundsFlow = ai.defineFlow(
  {
    name: 'transferFundsFlow',
    inputSchema: TransferFundsInputSchema,
    outputSchema: TransferFundsOutputSchema,
  },
  async (input) => {
    const { firestore } = initializeFirebase();
    const { senderId, recipientEmail, amount } = input;

    try {
      // 1. Find the recipient user by email
      const usersRef = collection(firestore, 'users');
      const q = query(usersRef, where('email', '==', recipientEmail));
      const querySnapshot = await getDocs(q);

      if (querySnapshot.empty) {
        return { success: false, message: 'Recipient not found.' };
      }

      const recipientDoc = querySnapshot.docs[0];
      const recipient = recipientDoc.data() as User;
      const recipientId = recipient.id;

      if (senderId === recipientId) {
        return { success: false, message: 'You cannot send money to yourself.' };
      }
      
      const senderWalletRef = doc(firestore, 'wallets', senderId);
      const recipientWalletRef = doc(firestore, 'wallets', recipientId);
      const senderDocSnap = await getDocs(query(collection(firestore, 'users'), where('id', '==', senderId)));
      const sender = senderDocSnap.docs[0].data() as User;


      // 2. Run the transfer within a Firestore transaction
      await runTransaction(firestore, async (transaction) => {
        const senderWalletDoc = await transaction.get(senderWalletRef);

        if (!senderWalletDoc.exists()) {
          throw new Error("Sender's wallet does not exist.");
        }

        const senderBalance = senderWalletDoc.data().balance;
        if (senderBalance < amount) {
          throw new Error('Insufficient funds.');
        }

        // Debit sender
        transaction.update(senderWalletRef, { balance: senderBalance - amount });

        // Credit recipient
        transaction.update(recipientWalletRef, { balance: recipient.balance + amount });
        
        // Create transaction records for both users
        const now = new Date().toISOString();
        const senderTransactionRef = doc(collection(firestore, `wallets/${senderId}/transactions`));
        transaction.set(senderTransactionRef, {
            id: senderTransactionRef.id,
            walletId: senderId,
            type: 'debit',
            amount: amount,
            description: `Transfer to ${recipient.firstName} ${recipient.lastName}`,
            date: now,
            party: { name: `${recipient.firstName} ${recipient.lastName}`, avatarUrl: recipient.avatarUrl },
        });

        const recipientTransactionRef = doc(collection(firestore, `wallets/${recipientId}/transactions`));
        transaction.set(recipientTransactionRef, {
            id: recipientTransactionRef.id,
            walletId: recipientId,
            type: 'credit',
            amount: amount,
            description: `Transfer from ${sender.firstName} ${sender.lastName}`,
            date: now,
            party: { name: `${sender.firstName} ${sender.lastName}`, avatarUrl: sender.avatarUrl },
        });

      });

      return {
        success: true,
        message: `Successfully transferred ${new Intl.NumberFormat('en-NG', { style: 'currency', currency: 'NGN' }).format(amount)} to ${recipientEmail}.`,
      };
    } catch (error: any) {
      console.error('Transaction failed: ', error);
      return {
        success: false,
        message: error.message || 'An unexpected error occurred during the transfer.',
      };
    }
  }
);

// This is the wrapper function that client components will call.
export async function transferFunds(input: TransferFundsInput): Promise<TransferFundsOutput> {
  // In a real-world scenario with Firebase Auth, you would verify the sender's identity here
  // to ensure they are authorized to perform this action.
  // For this context, we trust the senderId provided by the client.
  return transferFundsFlow(input);
}
