'use client';

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { useFirestore, useUser } from '@/firebase';
import {
  doc,
  collection,
  writeBatch,
  increment,
} from 'firebase/firestore';
import { useToast } from '@/hooks/use-toast';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { PlusCircle } from 'lucide-react';
import { PlaceHolderImages } from '@/lib/placeholder-images';

const addFundsSchema = z.object({
  amount: z.coerce
    .number()
    .positive({ message: 'Amount must be positive.' })
    .min(100, { message: 'Minimum deposit is 100.' }),
});

export default function AddFundsDialog() {
  const [open, setOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { user } = useUser();
  const firestore = useFirestore();
  const { toast } = useToast();

  const form = useForm<z.infer<typeof addFundsSchema>>({
    resolver: zodResolver(addFundsSchema),
    defaultValues: {
      amount: 1000,
    },
  });

  async function onSubmit(values: z.infer<typeof addFundsSchema>) {
    if (!user) {
      toast({
        variant: 'destructive',
        title: 'Not authenticated',
        description: 'You must be logged in to add funds.',
      });
      return;
    }
    setIsSubmitting(true);

    try {
      const walletRef = doc(firestore, 'wallets', user.uid);
      const transactionsCol = collection(
        firestore,
        'wallets',
        user.uid,
        'transactions'
      );
      const newTransactionRef = doc(transactionsCol);

      const batch = writeBatch(firestore);

      // 1. Update wallet balance
      batch.update(walletRef, {
        balance: increment(values.amount),
      });

      // 2. Create new transaction document
      const selfAvatar = PlaceHolderImages.find(p => p.id === 'avatar-self')?.imageUrl;
      batch.set(newTransactionRef, {
        id: newTransactionRef.id,
        walletId: user.uid,
        type: 'credit',
        amount: values.amount,
        description: 'Account Top-up',
        date: new Date().toISOString(),
        party: {
          name: 'ZuriPay Top-up',
          avatarUrl: selfAvatar,
        },
      });

      await batch.commit();

      toast({
        title: 'Funds Added',
        description: `Successfully added ${new Intl.NumberFormat('en-NG', { style: 'currency', currency: 'NGN' }).format(values.amount)} to your wallet.`,
      });

      form.reset();
      setOpen(false);
    } catch (error) {
      console.error('Error adding funds:', error);
      toast({
        variant: 'destructive',
        title: 'Error',
        description: 'Could not add funds to your wallet. Please try again.',
      });
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button className="w-full justify-start" size="lg" variant="secondary">
          <PlusCircle className="mr-4" /> Add Funds
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Add Funds to Wallet</DialogTitle>
          <DialogDescription>
            Enter the amount you would like to add.
          </DialogDescription>
        </DialogHeader>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="amount"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Amount (NGN)</FormLabel>
                  <FormControl>
                    <Input type="number" placeholder="e.g., 5000" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <DialogFooter>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting ? 'Adding...' : 'Add Funds'}
              </Button>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}
